#!/usr/bin/env bash
# Docs sur téléphone : paysage pleinement utilisable (texte sur toute la hauteur, navigation par-dessus,
# carte des entités côte à côte) ; portrait avec un bandeau qui invite à tourner l'écran.
# Prérequis : apply-pistes-code.sh et apply-docs-defilement.sh.
# Usage (racine du repo) : bash apply-docs-telephone.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/docs/components/PortraitHint.tsx" 2>/dev/null | grep -qF "function PortraitHint"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "function CodeTrail" "apps/web/src/features/docs/entities/EntityExplorer.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-pistes-code.sh"; exit 1; }
grep -qF "h-dvh min-h-0" "apps/web/src/app/docs/layout.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-defilement.sh"; exit 1; }
MODIFIED=("apps/web/src/app/globals.css" "apps/web/src/features/docs/components/DocsLayout.tsx" "apps/web/src/features/docs/components/DocsMainScrollControls.tsx" "apps/web/src/features/docs/components/DocsRightAside.tsx" "apps/web/src/features/docs/components/DocsSidebar.tsx" "apps/web/src/features/docs/entities/EntityExplorer.tsx")
CREATED=("apps/web/src/features/docs/components/PortraitHint.tsx" "apps/web/src/features/docs/lib/docsScroller.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "function PortraitHint" "apps/web/src/features/docs/components/PortraitHint.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

